\set ON_ERROR_STOP 1
SET client_min_messages=warning;
CREATE SCHEMA t;
CREATE TABLE t.results(name text,ok boolean,detail text);
CREATE TABLE t.shops(tag text,result jsonb);
CREATE TABLE t.ids(tag text,id uuid);
CREATE FUNCTION t.expect(n text,b boolean,d text DEFAULT NULL) RETURNS void LANGUAGE sql AS $$ INSERT INTO t.results VALUES(n,b,d) $$;
CREATE FUNCTION t.error(n text,q text,c text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE q; PERFORM t.expect(n,false,'no error'); EXCEPTION WHEN others THEN PERFORM t.expect(n,split_part(SQLERRM,':',1)=c,SQLERRM); END; END $$;
CREATE FUNCTION t.as_user(u text,o uuid DEFAULT NULL) RETURNS void LANGUAGE sql AS $$ SELECT set_config('request.jwt.claim.sub',COALESCE(u,''),false),set_config('app.org_id','',false),set_config('request.headers',CASE WHEN o IS NULL THEN '{}' ELSE json_build_object('x-org-id',o)::text END,false) $$;
CREATE FUNCTION t.org(s text) RETURNS uuid LANGUAGE sql AS $$ SELECT (result->>'organization_id')::uuid FROM t.shops WHERE tag=s $$;
CREATE FUNCTION t.main(s text) RETURNS uuid LANGUAGE sql AS $$ SELECT (result->>'branch_id')::uuid FROM t.shops WHERE tag=s $$;
CREATE FUNCTION t.owner(s text) RETURNS uuid LANGUAGE sql AS $$ SELECT (result->>'owner_employee_id')::uuid FROM t.shops WHERE tag=s $$;
CREATE FUNCTION t.id(s text) RETURNS uuid LANGUAGE sql AS $$ SELECT id FROM t.ids WHERE tag=s $$;
CREATE FUNCTION t.hash(s text) RETURNS text LANGUAGE sql AS $$ SELECT md5(s)||md5(s) $$;
CREATE FUNCTION t.make(s text,email text,username text,role public.employee_role DEFAULT 'CASHIER',overrides jsonb DEFAULT '[]') RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE r jsonb; BEGIN r:=public.create_employee(s,NULL,email,username,role,ARRAY[t.main('a')],NULL,overrides,t.hash(s),now()+interval '3 days'); INSERT INTO t.ids VALUES(s,(r->>'employee_id')::uuid); RETURN (r->>'employee_id')::uuid; END $$;
GRANT USAGE ON SCHEMA t TO authenticated;
GRANT SELECT ON t.shops,t.ids TO authenticated;
GRANT INSERT ON t.results,t.ids TO authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA t TO authenticated;
SELECT t.as_user('f0000000-0000-0000-0000-000000000001');
INSERT INTO t.shops SELECT s,public.admin_provision_organization('O02 '||s,'o02-'||s,p,'Owner',s||'@example.com',NULL,'Main',t.hash('owner-'||s),now()+interval '1 day') FROM (VALUES('a','enterprise'),('b','enterprise'),('starter','starter'))v(s,p);
INSERT INTO auth.users(id,email) VALUES('a0200000-0000-4000-8000-000000000001','a@example.com'),('a0200000-0000-4000-8000-000000000002','b@example.com'),('a0200000-0000-4000-8000-000000000003','starter@example.com'),('a0200000-0000-4000-8000-000000000004','manager@example.com');
SELECT public.accept_invite(t.hash('owner-a'),'a0200000-0000-4000-8000-000000000001');
SELECT public.accept_invite(t.hash('owner-b'),'a0200000-0000-4000-8000-000000000002');
SELECT public.accept_invite(t.hash('owner-starter'),'a0200000-0000-4000-8000-000000000003');
INSERT INTO public.employees(organization_id,auth_user_id,full_name,role) VALUES(t.org('a'),'a0200000-0000-4000-8000-000000000004','Manager','BRANCH_MANAGER') RETURNING id \gset manager_
INSERT INTO public.employee_branches(organization_id,employee_id,branch_id) VALUES(t.org('a'),:'manager_id',t.main('a'));
INSERT INTO public.employee_permission_overrides(organization_id,employee_id,permission_key,granted) VALUES(t.org('a'),:'manager_id','employee.manage',true);
SELECT t.as_user('a0200000-0000-4000-8000-000000000001',t.org('a'));
SELECT t.make('staff','staff@example.com','STAFF','CASHIER','[{"key":"audit.view","granted":true}]');
SELECT t.expect('created employee branches overrides invite audit',(SELECT auth_user_id IS NULL AND username='staff' AND created_by=t.owner('a') FROM public.employees WHERE id=t.id('staff')) AND EXISTS(SELECT 1 FROM public.employee_branches WHERE employee_id=t.id('staff') AND branch_id=t.main('a')) AND EXISTS(SELECT 1 FROM public.employee_permission_overrides WHERE employee_id=t.id('staff') AND permission_key='audit.view' AND granted) AND EXISTS(SELECT 1 FROM public.invites WHERE employee_id=t.id('staff') AND invited_by=t.owner('a') AND accepted_at IS NULL AND revoked_at IS NULL) AND EXISTS(SELECT 1 FROM public.audit_log WHERE action='employee.created' AND entity_id=t.id('staff')));
SELECT t.error('email taken',$q$SELECT t.make('email-dupe','STAFF@example.com','other')$q$,'EMAIL_TAKEN');
SELECT t.error('username taken',$q$SELECT t.make('user-dupe','other@example.com','staff')$q$,'USERNAME_TAKEN');
SELECT t.error('login required',$q$SELECT t.make('no-login',NULL,NULL)$q$,'LOGIN_REQUIRED');
SELECT t.error('username invalid',$q$SELECT t.make('bad-login',NULL,'a!')$q$,'USERNAME_INVALID');
SELECT t.error('owner role forbidden',$q$SELECT t.make('owner-role','x@example.com',NULL,'OWNER')$q$,'ROLE_NOT_ALLOWED');
SELECT t.error('unknown override',$q$SELECT t.make('unknown','unknown@example.com',NULL,'CASHIER','[{"key":"unknown","granted":true}]')$q$,'UNKNOWN_PERMISSION');
SELECT t.error('branch required',$q$SELECT public.create_employee('No branch',NULL,'nb@example.com',NULL,'CASHIER','{}',NULL,'[]',t.hash('nb'),now()+interval '1 day')$q$,'BRANCH_REQUIRED');
SELECT t.error('foreign branch',$q$SELECT public.create_employee('Foreign',NULL,'foreign@example.com',NULL,'CASHIER',ARRAY[t.main('b')],NULL,'[]',t.hash('foreign'),now()+interval '1 day')$q$,'BRANCH_NOT_IN_ORG');
INSERT INTO public.branches(organization_id,code,name,is_active) VALUES(t.org('a'),'INACT','Inactive',false) RETURNING id \gset inactive_
SELECT t.error('inactive branch',format('SELECT public.create_employee(''Inactive'',NULL,''inact@example.com'',NULL,''CASHIER'',ARRAY[%L::uuid],NULL,''[]'',%L,now()+interval ''1 day'')',:'inactive_id',t.hash('inactive')),'BRANCH_INACTIVE');
SELECT t.make('username-only',NULL,'only.user');
SELECT t.expect('username only link delivery',(public.resend_employee_invite(t.id('username-only'),t.hash('username-resend'),now()+interval '1 day')->>'delivery')='link' AND (SELECT email IS NULL FROM public.employees WHERE id=t.id('username-only')) AND (public.invite_lookup(t.hash('username-resend'))->>'login')='only.user');
SELECT public.update_employee(t.id('staff'),'Staff edited','123','changed@example.com','staff','CASHIER',t.main('a'));
SELECT t.expect('pending login edit revokes invite',(SELECT revoked_at IS NOT NULL FROM public.invites WHERE token_hash=t.hash('staff')));
SELECT public.resend_employee_invite(t.id('staff'),t.hash('staff-resend'),now()+interval '1 day');
INSERT INTO auth.users(id,email) VALUES('a0200000-0000-4000-8000-000000000005','changed@example.com');
SELECT public.accept_invite(t.hash('staff-resend'),'a0200000-0000-4000-8000-000000000005');
SELECT t.error('linked login locked',$q$SELECT public.update_employee(t.id('staff'),'Staff',NULL,'other@example.com','staff','CASHIER',t.main('a'))$q$,'LOGIN_LOCKED');
SELECT t.error('linked invite cannot resend',$q$SELECT public.resend_employee_invite(t.id('staff'),t.hash('again'),now()+interval '1 day')$q$,'INVITE_ALREADY_ACCEPTED');
SELECT t.error('pending cannot reset',$q$SELECT public.create_password_reset(t.id('username-only'),t.hash('pending-reset'),now()+interval '1 hour')$q$,'EMPLOYEE_NOT_LINKED');
SELECT public.create_password_reset(t.id('staff'),t.hash('reset1'),now()+interval '1 hour');
SELECT t.expect('valid reset lookup',public.password_reset_lookup(t.hash('reset1'))->>'status'='valid' AND public.password_reset_lookup(t.hash('reset1'))->>'login'='staff');
SELECT t.expect('consume returns auth user',public.consume_password_reset(t.hash('reset1'))='a0200000-0000-4000-8000-000000000005');
SELECT t.error('reset single use',$q$SELECT public.consume_password_reset(t.hash('reset1'))$q$,'RESET_USED');
SELECT t.expect('one reset completed audit',(SELECT count(*)=1 FROM public.audit_log WHERE action='employee.password_reset_completed' AND entity_id=t.id('staff')));
SELECT public.create_password_reset(t.id('staff'),t.hash('reset2'),now()+interval '1 hour');
SELECT public.create_password_reset(t.id('staff'),t.hash('reset3'),now()+interval '1 hour');
SELECT t.expect('resend reset revokes prior',(SELECT revoked_at IS NOT NULL FROM public.password_resets WHERE token_hash=t.hash('reset2')));
UPDATE public.password_resets SET expires_at=now()-interval '1 second' WHERE token_hash=t.hash('reset3');
SELECT t.error('expired reset',$q$SELECT public.consume_password_reset(t.hash('reset3'))$q$,'RESET_EXPIRED');
SELECT public.create_password_reset(t.id('staff'),t.hash('reset4'),now()+interval '1 hour');
SELECT public.set_employee_active(t.id('staff'),false,'Disabled');
SELECT t.expect('deactivate revokes reset and audits',(SELECT NOT is_active FROM public.employees WHERE id=t.id('staff')) AND (SELECT revoked_at IS NOT NULL FROM public.password_resets WHERE token_hash=t.hash('reset4')) AND (SELECT count(*)=1 FROM public.audit_log WHERE action='employee.active_set' AND entity_id=t.id('staff') AND severity='warning' AND reason='Disabled'));
SELECT t.expect('inactive reset lookup not found',public.password_reset_lookup(t.hash('reset4'))->>'status'='not_found');
SELECT public.set_employee_active(t.id('staff'),false,'again');
SELECT t.expect('inactive no-op no audit',(SELECT count(*)=1 FROM public.audit_log WHERE action='employee.active_set' AND entity_id=t.id('staff')));
SELECT public.set_employee_active(t.id('staff'),true,NULL);
SELECT public.set_employee_active(t.id('username-only'),false,'Disabled');
SELECT t.expect('deactivate revokes invite',(SELECT revoked_at IS NOT NULL FROM public.invites WHERE token_hash=t.hash('username-resend')));
SELECT t.error('revoked invite cannot accept',$q$SELECT public.accept_invite(t.hash('username-resend'),'a0200000-0000-4000-8000-000000000005')$q$,'INVITE_USED');
SELECT t.error('owner update protected',$q$SELECT public.update_employee(t.owner('a'),'Owner',NULL,'a@example.com',NULL,'CASHIER',t.main('a'))$q$,'TARGET_NOT_ALLOWED');
SELECT t.error('owner deactivate protected',$q$SELECT public.set_employee_active(t.owner('a'),false,'x')$q$,'FORBIDDEN');
SELECT t.error('owner reset protected',$q$SELECT public.create_password_reset(t.owner('a'),t.hash('owner-reset'),now()+interval '1 hour')$q$,'TARGET_NOT_ALLOWED');
SELECT t.as_user('a0200000-0000-4000-8000-000000000004',t.org('a'));
SELECT t.error('self update protected',format('SELECT public.update_employee(%L,''Manager'',NULL,NULL,NULL,''CASHIER'',NULL)',:'manager_id'),'TARGET_NOT_ALLOWED');
SELECT t.error('self deactivate protected',format('SELECT public.set_employee_active(%L,false,''x'')',:'manager_id'),'FORBIDDEN');
SELECT t.error('self reset protected',format('SELECT public.create_password_reset(%L,%L,now()+interval ''1 hour'')',:'manager_id',t.hash('self-reset')),'TARGET_NOT_ALLOWED');
SELECT t.error('role escalation',$q$SELECT t.make('accountant','accountant@example.com',NULL,'ACCOUNTANT')$q$,'PERMISSION_ESCALATION');
SELECT t.error('override escalation',$q$SELECT t.make('escalated','escalated@example.com',NULL,'CASHIER','[{"key":"org.settings_manage","granted":true}]')$q$,'PERMISSION_ESCALATION');
SELECT t.make('manager-created','manager-created@example.com',NULL);
SELECT t.expect('manager may create cashier',t.id('manager-created') IS NOT NULL);
SELECT t.error('F06 override escalation',$q$SELECT public.set_employee_permission(t.id('manager-created'),'org.settings_manage',true,'test')$q$,'FORBIDDEN');
INSERT INTO public.branches(organization_id,code,name) VALUES(t.org('a'),'SCOPE','Unassigned') RETURNING id \gset scoped_
SELECT t.error('F06 inaccessible branch',format('SELECT public.set_employee_branches(%L,ARRAY[%L::uuid],''test'')',t.id('manager-created'),:'scoped_id'),'FORBIDDEN');
SELECT t.as_user('a0200000-0000-4000-8000-000000000001',t.org('a'));
SELECT public.set_employee_permission(t.id('staff'),'audit.view',false,'revoke');
SELECT t.as_user('a0200000-0000-4000-8000-000000000005',t.org('a'));
SELECT t.expect('permission revoked immediately',NOT app.has_permission('audit.view'));
SELECT t.error('cashier create denied',$q$SELECT t.make('cashier-denied','denied@example.com',NULL)$q$,'PERMISSION_DENIED');
SELECT t.as_user('a0200000-0000-4000-8000-000000000001',t.org('a'));
SELECT public.set_employee_permission(t.id('staff'),'audit.view',true,'grant');
SELECT t.as_user('a0200000-0000-4000-8000-000000000005',t.org('a'));
SELECT t.expect('permission granted immediately',app.has_permission('audit.view'));
SELECT t.as_user('a0200000-0000-4000-8000-000000000001',t.org('a'));
SELECT t.error('foreign update',$q$SELECT public.update_employee(t.owner('b'),'Hijack',NULL,'b@example.com',NULL,'CASHIER',t.main('b'))$q$,'EMPLOYEE_NOT_FOUND');
SELECT t.error('foreign active',$q$SELECT public.set_employee_active(t.owner('b'),false,'x')$q$,'NOT_FOUND');
SELECT t.error('foreign invite',$q$SELECT public.resend_employee_invite(t.owner('b'),t.hash('foreign-invite'),now()+interval '1 day')$q$,'EMPLOYEE_NOT_FOUND');
SELECT t.error('foreign reset',$q$SELECT public.create_password_reset(t.owner('b'),t.hash('foreign-reset'),now()+interval '1 hour')$q$,'EMPLOYEE_NOT_FOUND');
SELECT t.expect('list scoped owner first',(SELECT id=t.owner('a') FROM public.list_employees(NULL,NULL,NULL,1,0)) AND NOT EXISTS(SELECT 1 FROM public.list_employees(NULL,NULL,NULL,100,0) WHERE id=t.owner('b')));
SELECT t.as_user('a0200000-0000-4000-8000-000000000003',t.org('starter'));
INSERT INTO t.ids SELECT 'starter-'||i,(public.create_employee('Pending '||i,NULL,'starter'||i||'@example.com',NULL,'CASHIER',ARRAY[t.main('starter')],NULL,'[]',t.hash('starter-'||i),now()+interval '1 day')->>'employee_id')::uuid FROM generate_series(1,4)i;
SELECT t.error('sixth user limit',$q$SELECT public.create_employee('Sixth',NULL,'sixth@example.com',NULL,'CASHIER',ARRAY[t.main('starter')],NULL,'[]',t.hash('sixth'),now()+interval '1 day')$q$,'PLAN_LIMIT_REACHED');
SELECT t.expect('limit leaves no partial rows',(SELECT count(*)=5 FROM public.employees WHERE organization_id=t.org('starter')) AND NOT EXISTS(SELECT 1 FROM public.invites WHERE token_hash=t.hash('sixth')));
SELECT public.set_employee_active(t.id('starter-1'),false,'free seat');
SELECT public.create_employee('Replacement',NULL,'replacement@example.com',NULL,'CASHIER',ARRAY[t.main('starter')],NULL,'[]',t.hash('replacement'),now()+interval '1 day');
SELECT t.error('reactivation limit',$q$SELECT public.set_employee_active(t.id('starter-1'),true,NULL)$q$,'PLAN_LIMIT_REACHED');
SELECT t.expect('service-only reset functions',NOT EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('password_reset_lookup','consume_password_reset') AND (has_function_privilege('anon',oid,'EXECUTE') OR has_function_privilege('authenticated',oid,'EXECUTE'))));
SELECT t.as_user('a0200000-0000-4000-8000-000000000001',t.org('a'));
SELECT t.error('invite expiry max',$q$SELECT public.resend_employee_invite(t.id('manager-created'),t.hash('too-long'),now()+interval '8 days')$q$,'INVITE_EXPIRY_INVALID');
SELECT t.error('reset expiry max',$q$SELECT public.create_password_reset(t.id('staff'),t.hash('too-long-reset'),now()+interval '25 hours')$q$,'INVITE_EXPIRY_INVALID');
SELECT t.error('deactivate reason required',$q$SELECT public.set_employee_active(t.id('staff'),false,' ')$q$,'VALIDATION_FAILED');
SELECT t.expect('foreign employee unchanged',(SELECT is_active AND role='OWNER' AND full_name='Owner' FROM public.employees WHERE id=t.owner('b')));
SELECT t.expect('reset table service only',NOT has_table_privilege('authenticated','public.password_resets','SELECT') AND NOT has_table_privilege('anon','public.password_resets','SELECT') AND NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.password_resets'::regclass));
SELECT t.expect('pending filter excludes linked',NOT EXISTS(SELECT 1 FROM public.list_employees(NULL,NULL,'pending',100,0) WHERE invite_status<>'pending'));
SELECT name,ok,detail FROM t.results WHERE NOT COALESCE(ok,false);
SELECT count(*) FILTER(WHERE ok) passed,count(*) FILTER(WHERE NOT COALESCE(ok,false)) failed FROM t.results;
